function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const span = size === 'large' ? 1000000 : 3;
  const n = size === 'large' ? int(1500, 2000) : int(1, 13);
  const mode = rand();
  if (n < 7 || mode < 0.4) return [Array.from({ length: n }, () => int(-span, span))];
  // Build four parts with the same sum, separated by three random cuts.
  const sizes = [1, 1, 1, 1];
  for (let extra = n - 7; extra > 0; extra--) sizes[int(0, 3)]++;
  const small = size === 'large' ? 1000 : 3;
  const target = int(-small, small);
  const nums = [];
  sizes.forEach((length, part) => {
    const piece = Array.from({ length: length - 1 }, () => int(-small, small));
    piece.push(target - piece.reduce((a, b) => a + b, 0));
    nums.push(...piece);
    if (part < 3) nums.push(int(-span, span));
  });
  // Sometimes nudge one value so the split may break, which gives near-miss inputs.
  if (mode > 0.8) nums[int(0, n - 1)] += int(1, 2);
  return [nums.map(v => Math.max(-1000000, Math.min(1000000, v)))];
}
